def original_safe_error(action, error):
    name = type(error).__name__
    reason = str(error)
    code = reason if action in READONLY and name == 'Refused' and (reason in CODES) else 'fixed_source_refusal_hidden'
    value = {'ok': False, 'stage': action if action in READONLY else 'fixed_RPC', 'error_type': name if name in ('Refused', 'ValueError', 'TimeoutError', 'OSError', 'FileNotFoundError', 'PermissionError') else 'OtherException', 'source_reason_code': code, 'errno': error.errno if isinstance(error, OSError) and error.errno in (2, 5, 13, 22, 28, 32, 110, 111) else None, 'automatic_retry': False, 'raw_output_archived': False}
    value.update(location(error))
    return value

def location(error):
    out = {'source_location': None, 'proc_path': None}
    allowed = APPROVED_TRACE_FILES
    if type(allowed) in (tuple, list):
        tb = error.__traceback__
        while tb is not None:
            code = tb.tb_frame.f_code
            if code.co_filename in allowed and type(tb.tb_lineno) is int and (0 < tb.tb_lineno < 100000) and re.fullmatch('[A-Za-z_][A-Za-z0-9_<>]{0,100}', code.co_name):
                out['source_location'] = {'source': code.co_filename, 'function': code.co_name, 'line': tb.tb_lineno}
            tb = tb.tb_next
    name = error.filename if isinstance(error, OSError) else None
    if type(name) is str and len(name) <= 128 and re.fullmatch('/proc/[0-9]{1,10}/(?:stat|exe|environ|cgroup|fd/[0-9]{1,10})', name):
        out['proc_path'] = name
    return out
